// Valid reports whether c is a known class.
func (c PlayerClass) Valid() bool {
	return c >= 0 && int(c) < len(playerClassInfos) && playerClassInfos[c].java != ""
}

// String returns the Mobius constant name of c, such as FIGHTER.
func (c PlayerClass) String() string {
	if !c.Valid() {
		return "PlayerClass(" + strconv.Itoa(int(c)) + ")"
	}
	return playerClassInfos[c].java
}

// IsMage reports whether c is a mystic class.
func (c PlayerClass) IsMage() bool { return c.Valid() && playerClassInfos[c].mage }

// IsSummoner reports whether c is a summoner class.
func (c PlayerClass) IsSummoner() bool { return c.Valid() && playerClassInfos[c].summoner }

// Race returns the race of c.
func (c PlayerClass) Race() Race {
	if !c.Valid() {
		return RaceNone
	}
	return playerClassInfos[c].race
}

// Parent returns the class c transfers from; false for a root class.
func (c PlayerClass) Parent() (PlayerClass, bool) {
	if !c.Valid() || playerClassInfos[c].parent < 0 {
		return 0, false
	}
	return playerClassInfos[c].parent, true
}

// Level returns the class level: 0 for a starting class, 1 after the
// first class transfer, 2 and 3 after the second and third.
func (c PlayerClass) Level() int {
	if !c.Valid() {
		return 0
	}
	return playerClassInfos[c].level
}

